import { useState } from 'react';
import { createClient } from '@supabase/supabase-js';

const supabaseUrl = 'https://aejnfgtttbenrnlmrsam.supabase.co';
const supabaseKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImFlam5mZ3R0dGJlbnJubG1yc2FtIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzQ2Mzk5NTMsImV4cCI6MjA5MDIxNTk1M30.8fLf1gmgdtF3J0JaLX_LC73Jk15N451zAfiM6NuDXdU';
const supabase = createClient(supabaseUrl, supabaseKey);

const LW360_LOGO = 'data:image/jpeg;base64,';

export default function App() {
  const [step, setStep] = useState('login');
  const [companyCode, setCompanyCode] = useState('');
  const [employeeId, setEmployeeId] = useState('');
  const [loading, setLoading] = useState(false);
  const [employee, setEmployee] = useState(null);
  const [organization, setOrganization] = useState(null);
  const [optedOut, setOptedOut] = useState(false);

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const { data: org } = await supabase.from('organizations').select('*').or(`code.eq.${companyCode},intake_code.eq.${companyCode}`).single();
      if (!org) throw new Error('Company not found');
      const { data: emp } = await supabase.from('employees').select('*').eq('organization_id', org.id).eq('employee_id_external', employeeId).single();
      if (!emp) throw new Error('Employee not found');
      setOrganization(org);
      setEmployee(emp);
      setStep('benefits');
      await supabase.from('employees').update({ enrollment_page_viewed_at: new Date().toISOString(), enrollment_status: 'Viewed' }).eq('id', emp.id);
    } catch (err) {
      alert('Login failed: ' + err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleOptOut = async () => {
    if (!confirm('Are you sure you want to opt out? You will not receive this benefit.')) return;
    setLoading(true);
    try {
      await supabase.from('employees').update({ enrollment_status: 'Opted Out', opted_out_at: new Date().toISOString() }).eq('id', employee.id);
      setOptedOut(true);
      setStep('optout');
    } catch (err) {
      alert('Error: ' + err.message);
    } finally {
      setLoading(false);
    }
  };

  if (step === 'optout') {
    return (
      <div style={{ minHeight: '100vh', background: 'linear-gradient(135deg, #1e3a5f 0%, #2d5a87 100%)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '24px' }}>
        <div style={{ backgroundColor: 'white', borderRadius: '16px', padding: '48px', maxWidth: '500px', textAlign: 'center' }}>
          <img src={LW360_LOGO} alt="Live Well 360" style={{ height: '80px', marginBottom: '24px' }} />
          <h2 style={{ color: '#1e293b', marginBottom: '16px' }}>Opt-Out Confirmed</h2>
          <p style={{ color: '#64748b' }}>You have opted out of the Live Well 360 wellness benefit. If you change your mind, please contact your HR department.</p>
        </div>
      </div>
    );
  }

  if (step === 'login') {
    return (
      <div style={{ minHeight: '100vh', background: 'linear-gradient(135deg, #1e3a5f 0%, #2d5a87 100%)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '24px' }}>
        <div style={{ backgroundColor: 'white', borderRadius: '16px', padding: '48px', maxWidth: '400px', width: '100%', boxShadow: '0 20px 60px rgba(0,0,0,0.3)' }}>
          <div style={{ textAlign: 'center', marginBottom: '32px' }}>
            <img src={LW360_LOGO} alt="Live Well 360" style={{ height: '80px', marginBottom: '16px' }} />
            <h2 style={{ color: '#1e293b', margin: 0 }}>View Your Benefits</h2>
            <p style={{ color: '#64748b', fontSize: '14px', marginTop: '8px' }}>Enter your company code and employee ID</p>
          </div>
          <form onSubmit={handleLogin}>
            <div style={{ marginBottom: '16px' }}>
              <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500, color: '#374151', fontSize: '14px' }}>Company Code</label>
              <input value={companyCode} onChange={(e) => setCompanyCode(e.target.value.toUpperCase())} required placeholder="e.g., FOUNDATIONE26" style={{ width: '100%', padding: '12px 16px', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '16px' }} />
            </div>
            <div style={{ marginBottom: '24px' }}>
              <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500, color: '#374151', fontSize: '14px' }}>Employee ID</label>
              <input value={employeeId} onChange={(e) => setEmployeeId(e.target.value.toUpperCase())} required placeholder="e.g., EMP001" style={{ width: '100%', padding: '12px 16px', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '16px' }} />
            </div>
            <button type="submit" disabled={loading} style={{ width: '100%', padding: '14px', backgroundColor: '#7AC143', color: 'white', border: 'none', borderRadius: '8px', fontSize: '16px', fontWeight: 600, cursor: loading ? 'not-allowed' : 'pointer' }}>{loading ? 'Loading...' : 'View My Benefits'}</button>
          </form>
        </div>
      </div>
    );
  }

  const benefit = employee?.net_benefit_monthly || 77.77;

  return (
    <div style={{ minHeight: '100vh', backgroundColor: '#f8fafc' }}>
      {/* Header */}
      <header style={{ background: 'linear-gradient(135deg, #1e3a5f 0%, #2d5a87 100%)', padding: '24px', textAlign: 'center' }}>
        <img src={LW360_LOGO} alt="Live Well 360" style={{ height: '60px', marginBottom: '8px' }} />
        <p style={{ color: 'rgba(255,255,255,0.8)', fontSize: '14px' }}>{organization?.name || organization?.company_name}</p>
      </header>

      <main style={{ maxWidth: '600px', margin: '0 auto', padding: '24px' }}>
        {/* Greeting */}
        <div style={{ textAlign: 'center', marginBottom: '24px' }}>
          <h2 style={{ color: '#1e293b', marginBottom: '8px' }}>Hi {employee?.first_name || 'there'}!</h2>
          <p style={{ color: '#64748b' }}>Here's your personalized benefit summary</p>
        </div>

        {/* Benefit Card */}
        <div style={{ background: 'linear-gradient(135deg, #1e3a5f 0%, #2d5a87 100%)', borderRadius: '16px', padding: '32px', textAlign: 'center', marginBottom: '24px', color: 'white' }}>
          <p style={{ fontSize: '14px', opacity: 0.8, marginBottom: '8px' }}>YOUR ESTIMATED MONTHLY BENEFIT</p>
          <div style={{ fontSize: '48px', fontWeight: 700, color: '#7AC143' }}>${benefit.toFixed(2)}</div>
          <p style={{ fontSize: '14px', opacity: 0.8, marginTop: '8px' }}>More take-home pay + wellness services</p>
        </div>

        {/* Benefits List */}
        <div style={{ backgroundColor: 'white', borderRadius: '12px', padding: '24px', marginBottom: '24px', boxShadow: '0 2px 8px rgba(0,0,0,0.1)' }}>
          <h3 style={{ color: '#1e293b', marginBottom: '16px' }}>What's Included</h3>
          {[
            { icon: '💰', title: 'Increased Take-Home Pay', desc: 'Tax-advantaged payroll structure' },
            { icon: '🏥', title: 'MDLive Telehealth', desc: '24/7 access to doctors via phone or video' },
            { icon: '🧠', title: 'AllOne Health EAP', desc: 'Counseling and support services' },
            { icon: '💊', title: 'OVAL Rx', desc: 'Prescription discount program' }
          ].map((item, i) => (
            <div key={i} style={{ display: 'flex', gap: '12px', padding: '12px 0', borderBottom: i < 3 ? '1px solid #e2e8f0' : 'none' }}>
              <div style={{ fontSize: '24px' }}>{item.icon}</div>
              <div><div style={{ fontWeight: 600, color: '#1e293b' }}>{item.title}</div><div style={{ fontSize: '14px', color: '#64748b' }}>{item.desc}</div></div>
            </div>
          ))}
        </div>

        {/* Auto-enrollment notice */}
        <div style={{ backgroundColor: '#fef3c7', borderRadius: '12px', padding: '16px', marginBottom: '24px', border: '1px solid #fcd34d' }}>
          <p style={{ color: '#92400e', fontSize: '14px', margin: 0 }}><strong>Auto-Enrollment:</strong> You will be automatically enrolled in 14 days unless you opt out below.</p>
        </div>

        {/* Opt-out button */}
        <button onClick={handleOptOut} disabled={loading} style={{ width: '100%', padding: '14px', backgroundColor: 'white', color: '#dc2626', border: '2px solid #dc2626', borderRadius: '8px', fontSize: '16px', fontWeight: 500, cursor: 'pointer' }}>
          {loading ? 'Processing...' : 'Opt Out of This Benefit'}
        </button>

        {/* Footer */}
        <div style={{ textAlign: 'center', marginTop: '32px', color: '#64748b', fontSize: '12px' }}>
          <p>Questions? Call (806) 799-1099</p>
          <p>Live Well 360 Health Strategy Advisors</p>
        </div>
      </main>
    </div>
  );
}
